import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline
import os
import subprocess
def _ensure_cutlass_include():
    """Locate (or fetch) the CUTLASS/CuTe headers required by the custom
    CUTE-based conv_transpose3d kernel below. This does not change the
    kernel's algorithm/intent; it only ensures nvcc can find `cute/tensor.hpp`.
    """
    candidates = []
    env_path = os.environ.get("CUTLASS_HOME")
    if env_path:
        candidates.append(env_path)
    candidates.append("/opt/cutlass")
    candidates.append(os.path.expanduser("~/cutlass"))
    candidates.append("/tmp/cutlass_cute")
    for c in candidates:
        inc = os.path.join(c, "include")
        if os.path.isfile(os.path.join(inc, "cute", "tensor.hpp")):
            return inc
    try:
        import cutlass  # nvidia-cutlass pip package, if installed
        pkg_dir = os.path.dirname(cutlass.__file__)
        for inc in (
            os.path.join(pkg_dir, "include"),
            os.path.join(os.path.dirname(pkg_dir), "include"),
        ):
            if os.path.isfile(os.path.join(inc, "cute", "tensor.hpp")):
                return inc
    except ImportError:
        pass
    target = "/tmp/cutlass_cute"
    if not os.path.isfile(os.path.join(target, "include", "cute", "tensor.hpp")):
        try:
            subprocess.run(
                ["git", "clone", "--depth", "1",
                 "https://github.com/NVIDIA/cutlass.git", target],
                check=True,
            )
        except Exception:
            pass
    inc = os.path.join(target, "include")
    if os.path.isfile(os.path.join(inc, "cute", "tensor.hpp")):
        return inc
    raise RuntimeError(
        "Could not locate or fetch CUTLASS/CuTe headers (cute/tensor.hpp). "
        "Set the CUTLASS_HOME environment variable to a CUTLASS checkout, "
        "or install a CUTLASS build that includes the CuTe headers."
    )
_cutlass_include = _ensure_cutlass_include()

